% Given data
t = [0 1 2 3 4];
k = [0.10 0.25 0.35 0.40 0.42];

dt = t(2) - t(1);

% Hybrid integration
I_38 = 3*dt/8 * ...
    (k(2) + 3*k(3) + 3*k(4) + k(5));

I_trap = dt/2 * (k(1) + k(2));

I = I_38 + I_trap;

figure; %[output:9fd65eac]
hold on; %[output:9fd65eac]

%%\ Simpson's 3/8 region [0,3]

% Fit cubic polynomial through first 4 points
p = polyfit(t(2:5), k(2:5), 3);

% Generate smooth curve
x1 = linspace(1, 4, 150);
y1 = polyval(p, x1);

% Shade area under cubic curve
patch([x1 fliplr(x1)], ... %[output:9fd65eac]
    [zeros(size(x1)) fliplr(y1)], ... %[output:9fd65eac]
    [0.65 0.82 1.0], ... %[output:9fd65eac]
    'FaceAlpha', 0.4, ... %[output:9fd65eac]
    'EdgeColor', 'none', ... %[output:9fd65eac]
    'HandleVisibility', 'off'); %[output:9fd65eac]

% Plot cubic interpolation
plot(x1, y1, 'b-', ... %[output:9fd65eac]
    'LineWidth', 2, ... %[output:9fd65eac]
    'DisplayName', "Cubic interpolation (Simpson's 3/8)"); %[output:9fd65eac]

%%\ Trapezoidal region [3,4]

% Shade trapezoidal area
patch([0 1 1 0], ... %[output:9fd65eac]
    [0 0 k(2) k(1)], ... %[output:9fd65eac]
    [0.65 0.82 1.0], ... %[output:9fd65eac]
    'FaceAlpha', 0.4, ... %[output:9fd65eac]
    'EdgeColor', 'none', ... %[output:9fd65eac]
    'HandleVisibility', 'off'); %[output:9fd65eac]

% Plot straight-line interpolation
plot(t(1:2), k(1:2), 'g-', ... %[output:9fd65eac]
    'LineWidth', 2, ... %[output:9fd65eac]
    'DisplayName', 'Linear interpolation (Trapezoidal)'); %[output:9fd65eac]

%%\ Given data points
plot(t, k, 'ro', ... %[output:9fd65eac]
    'MarkerFaceColor', 'r', ... %[output:9fd65eac]
    'MarkerSize', 7, ... %[output:9fd65eac]
    'DisplayName', 'Given data'); %[output:9fd65eac]

% Vertical lines at data points
for i = 1:length(t)
    plot([t(i) t(i)], [0 k(i)], ... %[output:9fd65eac]
        'k--', 'LineWidth', 0.8, ... %[output:9fd65eac]
        'HandleVisibility', 'off'); %[output:9fd65eac]
end

%%\ Formatting
xlabel('t (s)', 'FontSize', 12); %[output:9fd65eac]
ylabel('k (W/(m K))', ... %[output:9fd65eac]
    'FontSize', 12); %[output:9fd65eac]

title(sprintf('Hybrid Simpson''s 3/8 and Trapezoidal Rule (I = %.4f)', I)); %[output:9fd65eac]

legend('Location', 'southeast'); %[output:9fd65eac]
grid on; %[output:9fd65eac]
box on; %[output:9fd65eac]

xlim([0 4]); %[output:9fd65eac]
ylim([0 0.5]); %[output:9fd65eac]
xticks(0:1:4); %[output:9fd65eac]

set(gca, 'FontSize', 11); %[output:9fd65eac]
hold off; %[output:9fd65eac]

%%\ Display results
fprintf('Simpson 3/8 integral = %.5f\n', I_38); %[output:71f8cf18]
fprintf('Trapezoidal integral = %.5f\n', I_trap); %[output:75956aa9]
fprintf('Total integral       = %.5f\n', I); %[output:6130c1e5]

% Export for Overleaf after confirming the plot works
 exportgraphics(gcf, 'tr-s38.pdf', ... %[output:group:810cd0ea] %[output:9fd65eac]
     'ContentType', 'vector'); %[output:group:810cd0ea] %[output:9fd65eac]


